INSERT INTO `file_download` (`id`, `version_no`, `title`, `file_url`, `status`, `unique_hash`, `ra_jr`, `approved_on`, `congress`, `source_priority_level`, `event_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, NULL, 'An Act Strengthening the Anti-Hospital Deposit Law to Penalize Refusal of Treatment During Emergencies. This measure aims to ensure that all patients, regardless of financial capability, receive timely medical attention during emergencies. It imposes stricter penalties on hospitals and clinics that deny urgent care based on inability to pay. The law reaffirms healthcare as a fundamental human right.', '[\"1751334143_Fast Moving Items.csv\"]', '1', '1WvkfKv73CW6EJLKyG7FSXYFQ1mjTHeh', '11500', '2024-01-07', '14th', 'Constitution', NULL, '2025-07-14 02:51:16', '2025-07-14 02:51:16', NULL),
(2, NULL, 'A Measure Promoting Digital Literacy Among Senior Citizens Across Rural Communities. The initiative seeks to bridge the digital divide by providing free training programs on basic computer skills and internet usage. Special focus will be given to mobile banking, online communication, and accessing government services. The goal is to empower seniors to fully participate in an increasingly digital society.', '[\"1751334143_Fast Moving Items.csv\"]', '1', 'M8vo2L2mdakFIRwifMI7gdtdVCpUFSQ5', '11501', '2024-12-28', '12th', 'Sona Measure', NULL, '2025-07-14 02:51:16', '2025-07-14 02:51:16', NULL),
(3, NULL, 'An Act Mandating Free Annual Physical Exams for Public School Teachers. This law guarantees government-funded medical check-ups to monitor and maintain the health of educators. It recognizes the physical and mental demands placed on teachers and aims to provide early detection of common illnesses. Healthier teachers result in better educational outcomes for students.', '[\"1751334143_Fast Moving Items.csv\"]', '1', '4XK0ieNmpOy2NOxXVgD8XQiAia4L9xEg', '11502', '2023-12-15', '10th', 'Constitution', NULL, '2025-07-14 02:51:16', '2025-07-14 02:51:16', NULL),
(4, NULL, 'A Directive Establishing a National Food Waste Reduction Program. This directive encourages households, restaurants, and food businesses to adopt sustainable practices to minimize waste. It includes incentives for donations of surplus food and penalties for excessive discarding of edible goods. The program aligns with global environmental goals and addresses local food insecurity.', '[\"1751334143_Fast Moving Items.csv\"]', '1', '9g6T6tGO7y6b0fxX58YfleqvDGdOousy', '11503', '2025-03-02', '8th', 'Sona Measure', NULL, '2025-07-14 02:51:16', '2025-07-14 02:51:16', NULL),
(5, NULL, 'A Law Encouraging the Use of Renewable Energy in All Government Buildings. The legislation mandates the installation of solar panels, wind turbines, or other clean energy systems in public offices and facilities. It also provides funding for retrofitting older structures to improve energy efficiency. By leading by example, the government aims to reduce carbon emissions nationwide.', '[\"1751334143_Fast Moving Items.csv\"]', '1', 'lVomcsM8Mx8juSK09oY4CY0MuVz7G6Hh', '11504', '2025-06-17', '16th', 'Sona Measure', NULL, '2025-07-14 02:51:16', '2025-07-14 02:51:16', NULL),
(6, NULL, 'An Act Enhancing Cybersecurity Measures in Financial Institutions. This act compels banks and fintech firms to strengthen their data protection frameworks through modern encryption and regular security audits. It also establishes a central cybersecurity command for rapid incident response. The law is designed to safeguard public trust and prevent financial data breaches.', '[\"1751334143_Fast Moving Items.csv\"]', '1', 'CrnTwuJMD0awT3nZ1215pGSxrQYXfcqb', '11505', '2025-06-06', '11th', 'Directive', NULL, '2025-07-14 02:51:16', '2025-07-14 02:51:16', NULL),
(7, NULL, 'A Measure Creating the National Center for Disease Control and Prevention. The center will serve as the primary agency for disease surveillance, outbreak response, and health crisis coordination. It will be equipped with modern labs and trained personnel to monitor public health threats. This measure ensures the country is better prepared for pandemics and health emergencies.', '[\"1751334143_Fast Moving Items.csv\"]', '1', 'kOgpLdUBl9HFNS37iFHj16TUh0YdIDQj', '11506', '2025-06-20', '13th', 'Constitution', NULL, '2025-07-14 02:51:16', '2025-07-14 02:51:16', NULL),
(8, NULL, 'A Directive Implementing Mandatory Disaster Preparedness Drills in All Schools. The policy requires quarterly earthquake, fire, and evacuation drills for both students and staff. It aims to instill a culture of readiness and reduce panic during actual emergencies. The directive also mandates the updating of school safety protocols and evacuation maps.', '[\"1751334143_Fast Moving Items.csv\"]', '1', 'k2jSTs8Nnl5EigFOux9tbjKV1w1pkMgq', '11507', '2023-10-28', '16th', 'Sona Measure', NULL, '2025-07-14 02:51:16', '2025-07-14 02:51:16', NULL),
(9, NULL, 'An Act Expanding the Scholarship Coverage for Indigenous and Marginalized Students. This legislation provides full tuition and stipend support for qualified learners in both secondary and tertiary levels. It recognizes the systemic barriers faced by underrepresented communities in accessing education. The act aims to promote equality and inclusive development through learning.', '[\"1751334143_Fast Moving Items.csv\"]', '1', 'JzJSH7LgTUSsUuaJ3HEh1eev4IR5HGgN', '11508', '2024-08-18', '8th', 'Constitution', NULL, '2025-07-14 02:51:16', '2025-07-14 02:51:16', NULL),
(10, NULL, 'A Law Requiring Transparency in Public Infrastructure Projects Through Real-Time Monitoring Portals. This measure mandates the creation of online platforms where citizens can view updates on government-funded construction. It includes geotagged photos, project timelines, and budget breakdowns. Transparency is expected to reduce corruption and improve project efficiency.', '[\"1751334143_Fast Moving Items.csv\"]', '1', 'zK2BFNnSkXjHrQqkduTpZVF70eK6SVff', '11509', '2024-12-07', '11th', 'Directive', NULL, '2025-07-14 02:51:16', '2025-07-14 02:51:16', NULL),
(11, NULL, 'An Act Strengthening the Anti-Hospital Deposit Law to Penalize Refusal of Treatment During Emergencies. This measure aims to ensure that all patients, regardless of financial capability, receive timely medical attention during emergencies. It imposes stricter penalties on hospitals and clinics that deny urgent care based on inability to pay. The law reaffirms healthcare as a fundamental human right.', '[\"1751334143_Fast Moving Items.csv\"]', '1', 'IEFMlK8T1pxU1Dy8FcdNJGWf0w7TD18U', '11510', '2024-04-07', '15th', 'Constitution', NULL, '2025-07-14 02:51:16', '2025-07-14 02:51:16', NULL),
